syntax = "proto3";
package doze;

message Event {
  string name = 1;
  repeated string tags = 3;
  .doze.Event.Kind kind = 4;
  repeated .doze.Event.AttrsEntry attrs = 5;
  .doze.Other other = 6;

  oneof when {
    int64 at = 2;
  }

  message AttrsEntry {
    option map_entry = true;

    string key = 1;
    string value = 2;
  }
  enum Kind {
    UNKNOWN = 0;
  }
}
message Other {
  string x = 1;
}

syntax = "proto3";

message M {
  .Color c = 1;

  message In {
    int32 v = 1;
  }
}
enum Color {
  RED = 0;
  BLUE = 1;
}

package p2;

option java_package = "dev.doze";
option java_multiple_files = true;
option go_package = "example.com/p2";

message Req {
  reserved 10 to 11;
  reserved 20;
  reserved "gone";

  required string id = 1;
  optional string note = 2 [default = "hi"];
  repeated int32 n = 3 [packed = true];
  optional bool old = 4 [deprecated = true];

  enum E {
    option allow_alias = true;
    A = 0;
    B = 0;
  }
}

syntax = "proto3";
package w;

import "google/protobuf/timestamp.proto";

message M {
  optional string maybe = 1;
  .google.protobuf.Timestamp at = 2;
  bytes raw = 3;

  oneof choice {
    string a = 4;
    int32 b = 5;
  }
}

syntax = "proto3";
package s;

message Q {}
message R {}

service Svc {
  rpc One (.s.Q) returns (.s.R);
  rpc Many (stream .s.Q) returns (stream .s.R);
}
